"""Contact sheet text for substitute teachers."""

from typing import List, Sequence, Tuple

from rosterkit.errors import ProjectError
from rosterkit.models import Student


def _cells(student: Student) -> Tuple[str, str, str]:
    if not student.email:
        raise ProjectError(
            f"no email for {student.display_name}"
        )
    name = student.display_name
    return (name, student.section, student.email)


def _join(row: Sequence[str], widths: List[int]) -> str:
    padded = [
        cell.ljust(width)
        for cell, width in zip(row, widths)
    ]
    return "  ".join(padded).rstrip()


def contact_rows(students: Sequence[Student]) -> List[str]:
    """Text rows of name, section and email, sorted by name.

    Raises ProjectError for an empty list or when a student
    has no email, naming that student.
    """
    if not students:
        raise ProjectError("no students to list")
    ordered = sorted(
        students,
        key=lambda item: item.display_name.lower()
    )
    cells = [_cells(item) for item in ordered]
    widths = [
        max(len(cell) for cell in column)
        for column in zip(*cells)
    ]
    return [_join(row, widths) for row in cells]

