# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.errors import ProjectError
from rosterkit.models import Student

def make_student(last, first, section, email):
    return Student("id", last, first, section, email)

class ContactRowsTests(unittest.TestCase):
    def test_sorted_by_name_and_aligned(self):
        rows = contact_rows([
            make_student("Young", "Al", "B", "al@x.org"),
            make_student(
                "Adams", "Beatrice", "A", "bea@x.org"
            )
        ])
        self.assertEqual(rows, [
            "Adams, Beatrice  A  bea@x.org",
            "Young, Al        B  al@x.org"
        ])

    def test_missing_email_names_the_student(self):
        students = [
            make_student("Adams", "Bea", "A", "bea@x.org"),
            make_student("Young", "Al", "B", None)
        ]
        with self.assertRaises(ProjectError) as caught:
            contact_rows(students)
        self.assertIn("Young, Al", str(caught.exception))

    def test_blank_email_is_missing(self):
        student = make_student("Young", "Al", "B", "")
        with self.assertRaises(ProjectError):
            contact_rows([student])

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])

if __name__ == "__main__":
    unittest.main()
